}

Method.Source:
    /// <summary>
    /// If site link is enabled, replaces the site linked dimension to match the site.
    /// </summary>
    /// <param name="_dimension">
    /// The dimension default value to change.
    /// </param>
    /// <param name="_inventLocationId">
    /// The location from which to default the dimension.
    /// </param>
    /// <returns>
    /// The resulting dimension.
    /// </returns>
    /// <remarks>
    /// If the site link is inactive, this method returns the dimension that was passed without any changes
    /// to it.
    /// </remarks>
    public static DimensionDefault changeDimension(DimensionDefault _dimension, InventLocationId _inventLocationId)
    {
        InventParameters inventParameters = InventParameters::find();

        if (inventParameters.isMultiSiteDimensionLinkInactive())
        {
            return _dimension;
        }

        DimensionDefault locationDimension = InventLocation::find(_inventLocationId).METDefaultDimension;
        DimensionDefault defaultDimension = LedgerDimensionDefaultFacade::serviceReplaceAttributeValue(_dimension, locationDimension, inventParameters.SiteDimensionAttribute);

        if (!DimensionAttributeDerivedDimensions::derivedDimensionsExist())
        {
            return defaultDimension;
        }

        // Deriving default dimensions linked to inventory site
        DimensionDefault derivedDimension = LedgerDimensionFacade::serviceApplyDerivedDimensionsForAttribute(defaultDimension,
            inventParameters.SiteDimensionAttribute,
            Ledger::current());

        // Merging derived default dimension linked to inventory site with original default dimension
        return LedgerDimensionDefaultFacade::serviceMergeDefaultDimensions(derivedDimension, defaultDimension);
    }

    public static InventLocation find(InventLocationId _inventLocation, boolean _update)
    {
        InventLocation inventLocation;

        Unchecked(Uncheck::XDS)
        {
            inventLocation = next find(_inventLocation, _update);
        }

        return inventLocation;
    }

